CLASH = [(c, v, tok, sg(c, v, tok, nth)) for c, v, tok, _, nth in SPEC if sg(c, v, tok, nth) in dict(GL)]; assert not CLASH, CLASH   # a seat patched by gloss is not patched again by reference
