MARK = 'THE DEUTERONOMY WALK sitting 18 (2026-09-26, Deuteronomy 26-28, LEAN)'
assert MARK not in t
M17 = 'THE DEUTERONOMY WALK sitting 17 (2026-09-26, Deuteronomy 22-25, LEAN)'
i = t.index(f'  # {M17}: the worst glosses of the four chapters\' seats')
j = t.index('\n', i) + 1
rows = []
while True:
    m = re.match(r'  "[^"]+": "[^"]*"[^\n]*\n', t[j:])
    if not m: break
    rows.append(m.group(0)); j += len(m.group(0))
assert len(rows) == 100, len(rows)   # sitting 17's by-gloss rows (the probe's walk 100)
A1 = rows[-1]; assert t.count(A1) == 1
gl_block = A1 + f'\n  # {MARK}: the worst glosses of the three chapters\' seats, the families probed in the store first (ch26_patch_probe.py) — the lean form\'s patch; the rest OWED (COMPILE_DEBT\'s lean-pass box)\n' + ''.join(f'  "{k}": "{v}"\n' for k, v in GL)
