m2 = re.search(r'^  "Deut\.25\.19:18": "the-memory-of"[^\n]*\n', t, re.M); assert m2 and t.count('"Deut.25.19:18": "the-memory-of"') == 1
A2 = m2.group(0)
ref_block = A2 + f'  # {MARK}: the three chapters\' seats by reference — the token named beside each; the indices the store\'s own (the seven "?" seats of anokhi read "I"; "cursed" at its sixteen seats)\n' + ''.join(f'  "{k}": "{v}"   # {TOK[k]}\n' for k, v in REF)
